<?php requireRole('tutor'); ?><section class="hero"><h1>👨‍🏫 Tutor Dashboard</h1><p>Manage one-to-one tutoring requests.</p></section><br><div id="requests" class="grid"></div><script>async function load(){let a=await api('backend/api/tutor.php?action=requests');document.getElementById('requests').innerHTML=a.length?a.map(r=>`<div class="card"><h2>${escapeHTML(r.student)}</h2><p>Course: ${escapeHTML(r.course)}</p><p>Status: ${r.status}</p><p>Amount: ${r.amount_bhd} BHD</p><button class="btn" onclick="update(${r.id},'scheduled')">Schedule</button> <button class="btn secondary" onclick="update(${r.id},'completed')">Complete</button></div>`).join(''):'<div class="card">No tutoring requests.</div>'}async function update(id,status){let f=new FormData();f.append('action','update');f.append('id',id);f.append('status',status);f.append('csrf',window.CSRF);await post('backend/api/tutor.php',f);load()}load()</script>
